CREATE PROCEDURE dbo.DeleteSjJournalAtomic @JournalIdNo int AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF NOT EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo) RETURN 1;IF EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo AND Posted=1) THROW 51431,'Posted sales journals cannot be deleted.',1;IF EXISTS(SELECT 1 FROM dbo.SalesJournalItem i JOIN dbo.Reconciled r ON r.JournalCode='SJ' AND r.JournalItemIdNo=i.IdNo WHERE i.JournalIdNo=@JournalIdNo) THROW 51432,'Reconciled sales journals cannot be deleted.',1;IF EXISTS(SELECT 1 FROM dbo.ArOpenInvoice o JOIN dbo.CsrOiItem c ON c.ArOpenInvoiceIdNo=o.IdNo WHERE o.JournalCode='SJ' AND o.JournalIdNo=@JournalIdNo) OR EXISTS(SELECT 1 FROM dbo.ApOpenInvoice o JOIN dbo.CdOiItem c ON c.ApOpenInvoiceIdNo=o.IdNo WHERE o.JournalCode='SJ' AND o.JournalIdNo=@JournalIdNo) OR EXISTS(SELECT 1 FROM dbo.ApOpenInvoice o JOIN dbo.PcOiItem p ON p.ApOpenInvoiceIdNo=o.IdNo WHERE o.JournalCode='SJ' AND o.JournalIdNo=@JournalIdNo) OR EXISTS(SELECT 1 FROM dbo.ApOpenInvoice o JOIN dbo.CkOiItem k ON k.ApOpenInvoiceIdNo=o.IdNo WHERE o.JournalCode='SJ' AND o.JournalIdNo=@JournalIdNo) THROW 51434,'Sales journal open invoices with allocations cannot be deleted.',1;EXEC dbo.AssertJournalNotReconciliationLocked @JournalCode='SJ', @JournalIdNo=@JournalIdNo;BEGIN TRAN;BEGIN TRY DELETE FROM dbo.SalesDeposit WHERE SalesJournalIdNo=@JournalIdNo;DELETE FROM dbo.ArOpenInvoice WHERE JournalCode='SJ' AND JournalIdNo=@JournalIdNo;DELETE FROM dbo.ApOpenInvoice WHERE JournalCode='SJ' AND JournalIdNo=@JournalIdNo;DELETE FROM dbo.SalesJournalItem WHERE JournalIdNo=@JournalIdNo;DELETE FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo;COMMIT;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;THROW;END CATCH END;
GO
